               <label class="choice" for="q2-javascript">
                 <input type="checkbox" id="q2-javascript" name="q2" value="javascript">
                 <span class="choice-text">JavaScript</span>
               </label>
               <label class="choice" for="q2-css">
                 <input type="checkbox" id="q2-css" name="q2" value="css">
                 <span class="choice-text">CSS</span>
               </label>
               <label class="choice" for="q2-sql">
                 <input type="checkbox" id="q2-sql" name="q2" value="sql">
                 <span class="choice-text">SQL</span>
               </label>
               <label class="choice" for="q2-python">
                 <input type="checkbox" id="q2-python" name="q2" value="python">
                 <span class="choice-text">Python</span>
