         <div class="form-field" data-question="q3">
           <fieldset aria-describedby="q3-error">
             <legend>3. Which languages are statically typed by default?</legend>
             <div class="choices">
               <label class="choice" for="q3-java">
                 <input type="checkbox" id="q3-java" name="q3" value="java">
                 <span class="choice-text">Java</span>
               </label>
               <label class="choice" for="q3-csharp">
                 <input type="checkbox" id="q3-csharp" name="q3" value="csharp">
                 <span class="choice-text">C#</span>
               </label>
               <label class="choice" for="q3-ruby">
                 <input type="checkbox" id="q3-ruby" name="q3" value="ruby">
                 <span class="choice-text">Ruby</span>
               </label>
               <label class="choice" for="q3-go">
                 <input type="checkbox" id="q3-go" name="q3" value="go">
                 <span class="choice-text">Go</span>
               </label>
             </div>
             <p class="error" id="q3-error">Choose at least one answer for question 3.</p>
