         </div>

         <button type="submit">Submit quiz</button>
         <p class="result" id="quiz-result" aria-live="polite"></p>
       </form>
     </section>
   </main>

   <script>
     const form = document.querySelector("#quiz-form");
     const result = document.querySelector("#quiz-result");
     const answers = {
       q1: ["python", "javascript", "ruby"],
       q2: ["javascript", "css", "sql", "python"],
       q3: ["java", "csharp", "go"]
     };

     function getSelections(questionName) {
       return Array.from(form.querySelectorAll(`input[name="${questionName}"]:checked`))
         .map((input) => input.value)
         .sort();
     }

     function arraysMatch(first, second) {
       return first.length === second.length && first.every((value, index) => value === second[index]);
     }

     function setGroupInvalid(field, isInvalid) {
       field.dataset.invalid = String(isInvalid);
       field.querySelectorAll("input[type='checkbox']").forEach((input) => {
         input.setAttribute("aria-invalid", String(isInvalid));
       });
     }

     form.addEventListener("change", (event) => {
       if (!event.target.matches("input[type='checkbox']")) {
         return;
       }

       const field = event.target.closest(".form-field");
       const hasSelection = field.querySelector("input[type='checkbox']:checked");
       setGroupInvalid(field, !hasSelection);
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const fields = Array.from(form.querySelectorAll(".form-field"));
       const firstInvalidField = fields.find((field) => {
         const hasSelection = field.querySelector("input[type='checkbox']:checked");
         setGroupInvalid(field, !hasSelection);
         return !hasSelection;
       });

       if (firstInvalidField) {
         result.textContent = "Please answer every question before submitting.";
         firstInvalidField.querySelector("input[type='checkbox']").focus();
         return;
       }

       const score = Object.entries(answers).reduce((total, [questionName, correctAnswers]) => {
         const selections = getSelections(questionName);
         return total + (arraysMatch(selections, [...correctAnswers].sort()) ? 1 : 0);
       }, 0);

       result.textContent = `You scored ${score} out of 3.`;
     });
   </script>
 </body>
 </html>

